structured.c_draft:
#include <matrixLIB.h>
#include <builtin_MATH.h>
/* RTDS-style C draft for structured node elimination.
   RAM math reference may use matrix_Add/Sub/Mul on raw arrays.
   Runtime sections use MATRIX_ matrixDim/register/condition plus set_CODE,
   matrix_mult_CODE, matrix_matXvec_CODE, matrix_add_CODE/subtract_CODE,
   matrix_scalarMult_CODE, MATH_matx_invert,
   mat_2x2_sym_inv_code, mat_3x3_sym_inv_code. */
enum { NR = 9, NK = 3 };

/* RTDS lifecycle placement generated from final-expression dependency analysis.
   RAM_PASS1 stamps only RAM_CONSTANT Gred entries through g_mat_over.
   CODE/BEGIN_T0 computes only dynamic reduced-G and non-direct Ihisred paths.
   T1_T2 reads solved node voltages and recovers eliminated-node voltages when needed. */
STATIC:

    /* Runtime matrix objects */
    MATRIX_ Grr_code = {0};
    MATRIX_ Grk_code = {0};
    MATRIX_ Gkr_code = {0};
    MATRIX_ Gkk_code = {0};
    MATRIX_ Gred_code = {0};
    MATRIX_ Ihisr_code = {0};
    MATRIX_ Ihisk_code = {0};
    MATRIX_ Ihisred_code = {0};
    MATRIX_ Vr_code = {0};
    MATRIX_ Vk_code = {0};
    /* Runtime state */
    int rtds_matrix_code_ready = 0;
    /* User G/CODE symbols */
    double AN = 0.0;
    double AP = 0.0;
    double BN = 0.0;
    double BP = 0.0;
    double CN = 0.0;
    double CP = 0.0;
    double Dabc = 0.0;
    double G11 = 0.0;
    double G12 = 0.0;
    double G22 = 0.0;
    double Grc = 0.0;
    double PN = 0.0;
    double PP = 0.0;
    double gNN = 0.0;
    double w1 = 0.0;
    double w2 = 0.0;
    /* User Ihis/history symbols */
    double IAhis_rc = 0.0;
    double IBhis_rc = 0.0;
    double IC_his0 = 0.0;
    double IChis_rc = 0.0;
    double Ihis_A = 0.0;
    double Ihis_B = 0.0;
    double Ihis_C = 0.0;
    double Ihis_a = 0.0;
    double Ihis_b = 0.0;
    double Ihis_c = 0.0;
    double Ihis_exclude_c0 = 0.0;
    double Ihis_exclude_c1 = 0.0;
    double Ihis_exclude_c2 = 0.0;
    double Ihis_exclude_c3 = 0.0;
    double Ihis_exclude_c4 = 0.0;
    /* Block-matrix scalar aliases */
    double Gkk_shared_1 = 0.0;
    double Gkr_k1_N = 0.0;
    double Gkr_k1_P = 0.0;
    double Gkr_k2_N = 0.0;
    double Gkr_k2_P = 0.0;
    double Gkr_k3_N = 0.0;
    double Gkr_k3_P = 0.0;
    double Gkr_shared_1 = 0.0;
    double Gkr_shared_2 = 0.0;
    double Gkr_shared_3 = 0.0;
    double Gkr_shared_4 = 0.0;
    double Grk_N_k1 = 0.0;
    double Grk_N_k2 = 0.0;
    double Grk_N_k3 = 0.0;
    double Grk_P_k1 = 0.0;
    double Grk_P_k2 = 0.0;
    double Grk_P_k3 = 0.0;
    double Grk_shared_1 = 0.0;
    double Grk_shared_2 = 0.0;
    double Grk_shared_3 = 0.0;
    double Grk_shared_4 = 0.0;
    double Grr_G_G = 0.0;
    double Grr_N_N = 0.0;
    double Grr_P_P = 0.0;
    double Grr_shared_1 = 0.0;
    double Grr_shared_2 = 0.0;
    double Grr_shared_3 = 0.0;
    double Grr_shared_4 = 0.0;
    double W_shared_1 = 0.0;

LOCAL_STATIC:
    /* User RAM-only G symbols */
    double gC = 0.0;

RAM_PASS1:
    int err = 0;
    /* ************************************************************************
     * RAM-SIDE G MATRIX VALUE SETUP
     * Assign or compute every G-related value before any RAM-side use.
     * This section stamps only fixed g_mat_over entries; CODE-owned matrices are refreshed in CODE.
     * ************************************************************************ */



    g_mat_nods[0] = getNodeNum(comp, "P");
    g_mat_nods[1] = getNodeNum(comp, "N");
    /* g_mat_over is provided by the PSYS/CBuilder runtime; initialize, do not define it here. */
    for (int row = 0; row < 2; row++) {
        for (int col = 0; col < 2; col++) {
            g_mat_over[row][col] = 0.0;
        }
    }
    g_mat_over[0][0] = gC;
    g_mat_over[0][1] = -gC;
    g_mat_over[1][0] = -gC;
    g_mat_over[1][1] = gC;
    setupGMatrix(2);

    err += matrixDim(&Grr_code, NR, NR);
    err += matrixDim(&Grk_code, NR, NK);
    err += matrixDim(&Gkr_code, NK, NR);
    err += matrixDim(&Gkk_code, NK, NK);
    err += matrixDim(&Gred_code, NR, NR);
    err += matrixDim(&Ihisr_code, NR, 1);
    err += matrixDim(&Ihisk_code, NK, 1);
    err += matrixDim(&Ihisred_code, NR, 1);
    err += matrixDim(&Vr_code, NR, 1);
    err += matrixDim(&Vk_code, NK, 1);
    if (err > 0) {
        reportError_RW("network_node", STOP_IMMEDIATELY_CONDITION,
                       "RTDS matrix allocation failed for component %s.", Name);
    }
    matrix_register(&Grr_code);
    matrix_register(&Grk_code);
    matrix_register(&Gkr_code);
    matrix_register(&Gkk_code);
    matrix_register(&Gred_code);
    matrix_register(&Ihisr_code);
    matrix_register(&Ihisk_code);
    matrix_register(&Ihisred_code);
    matrix_register(&Vr_code);
    matrix_register(&Vk_code);

GVALUES:
    /* Dynamic reduced-G stamp handles, ordered by Gred upper triangle. */
    double varG_A_1_A_1 = createGValue("varG_A_1_A_1", "A_1", "A_1", 0, "TRUE");
    double varG_A_1_B_1 = createGValue("varG_A_1_B_1", "A_1", "B_1", 0, "TRUE");
    double varG_A_1_C_1 = createGValue("varG_A_1_C_1", "A_1", "C_1", 0, "TRUE");
    double varG_A_1_G = createGValue("varG_A_1_G", "A_1", "G", 0, "TRUE");
    double varG_A_1_RC_A = createGValue("varG_A_1_RC_A", "A_1", "RC_A", 0, "TRUE");
    double varG_A_1_RC_C = createGValue("varG_A_1_RC_C", "A_1", "RC_C", 0, "TRUE");
    double varG_A_1_P = createGValue("varG_A_1_P", "A_1", "P", 0, "TRUE");
    double varG_A_1_N = createGValue("varG_A_1_N", "A_1", "N", 0, "TRUE");
    double varG_B_1_B_1 = createGValue("varG_B_1_B_1", "B_1", "B_1", 0, "TRUE");
    double varG_B_1_C_1 = createGValue("varG_B_1_C_1", "B_1", "C_1", 0, "TRUE");
    double varG_B_1_G = createGValue("varG_B_1_G", "B_1", "G", 0, "TRUE");
    double varG_B_1_RC_A = createGValue("varG_B_1_RC_A", "B_1", "RC_A", 0, "TRUE");
    double varG_B_1_RC_B = createGValue("varG_B_1_RC_B", "B_1", "RC_B", 0, "TRUE");
    double varG_B_1_P = createGValue("varG_B_1_P", "B_1", "P", 0, "TRUE");
    double varG_B_1_N = createGValue("varG_B_1_N", "B_1", "N", 0, "TRUE");
    double varG_C_1_C_1 = createGValue("varG_C_1_C_1", "C_1", "C_1", 0, "TRUE");
    double varG_C_1_G = createGValue("varG_C_1_G", "C_1", "G", 0, "TRUE");
    double varG_C_1_RC_B = createGValue("varG_C_1_RC_B", "C_1", "RC_B", 0, "TRUE");
    double varG_C_1_RC_C = createGValue("varG_C_1_RC_C", "C_1", "RC_C", 0, "TRUE");
    double varG_C_1_P = createGValue("varG_C_1_P", "C_1", "P", 0, "TRUE");
    double varG_C_1_N = createGValue("varG_C_1_N", "C_1", "N", 0, "TRUE");
    double varG_G_G = createGValue("varG_G_G", "G", "G", 0, "TRUE");
    double varG_G_RC_A = createGValue("varG_G_RC_A", "G", "RC_A", 0, "TRUE");
    double varG_G_RC_B = createGValue("varG_G_RC_B", "G", "RC_B", 0, "TRUE");
    double varG_G_RC_C = createGValue("varG_G_RC_C", "G", "RC_C", 0, "TRUE");
    double varG_G_P = createGValue("varG_G_P", "G", "P", 0, "TRUE");
    double varG_G_N = createGValue("varG_G_N", "G", "N", 0, "TRUE");
    double varG_RC_A_RC_A = createGValue("varG_RC_A_RC_A", "RC_A", "RC_A", 0, "TRUE");
    double varG_RC_A_P = createGValue("varG_RC_A_P", "RC_A", "P", 0, "TRUE");
    double varG_RC_A_N = createGValue("varG_RC_A_N", "RC_A", "N", 0, "TRUE");
    double varG_RC_B_RC_B = createGValue("varG_RC_B_RC_B", "RC_B", "RC_B", 0, "TRUE");
    double varG_RC_B_P = createGValue("varG_RC_B_P", "RC_B", "P", 0, "TRUE");
    double varG_RC_B_N = createGValue("varG_RC_B_N", "RC_B", "N", 0, "TRUE");
    double varG_RC_C_RC_C = createGValue("varG_RC_C_RC_C", "RC_C", "RC_C", 0, "TRUE");
    double varG_RC_C_P = createGValue("varG_RC_C_P", "RC_C", "P", 0, "TRUE");
    double varG_RC_C_N = createGValue("varG_RC_C_N", "RC_C", "N", 0, "TRUE");
    double varG_P_P = createGValue("varG_P_P", "P", "P", 0, "TRUE");
    double varG_P_N = createGValue("varG_P_N", "P", "N", 0, "TRUE");
    double varG_N_N = createGValue("varG_N_N", "N", "N", 0, "TRUE");

CODE:
BEGIN_T0:
    if (!rtds_matrix_code_ready) {
        initializeMatricesForCode();
        conditionMatrixForCODE(&Grr_code);
        conditionMatrixForCODE(&Grk_code);
        conditionMatrixForCODE(&Gkr_code);
        conditionMatrixForCODE(&Gkk_code);
        conditionMatrixForCODE(&Gred_code);
        conditionMatrixForCODE(&Ihisr_code);
        conditionMatrixForCODE(&Ihisk_code);
        conditionMatrixForCODE(&Ihisred_code);
        conditionMatrixForCODE(&Vr_code);
        conditionMatrixForCODE(&Vk_code);
        rtds_matrix_code_ready = 1;
    }


    /* ************************************************************************
     * CODE-SIDE G MATRIX VALUE SETUP
     * Update runtime G-related symbols and matrices before the reduction math below.
     * Only matrices required by dynamic G, Ihis reduction, or Vk recovery are refreshed.
     * ************************************************************************ */



    /* Runtime refresh. Use set_CODE for matrices touched in CODE; do not write MATRIX_.p directly. */
    /* Grr_shared_1 represents Grr[A_1,A_1], Grr[B_1,B_1], Grr[C_1,C_1]: 2.0*G11 + 2.0*w1. */
    Grr_shared_1 = 2.0*G11 + 2.0*w1;
    /* Grr_shared_2 represents Grr[A_1,B_1], Grr[A_1,C_1], Grr[B_1,A_1], Grr[B_1,C_1], Grr[C_1,A_1], Grr[C_1,B_1]: -G11 - w1. */
    Grr_shared_2 = -G11 - w1;
    /* Grr_G_G represents Grr[G,G]: 3.0*G22 + 3.0*w2. */
    Grr_G_G = 3.0*G22 + 3.0*w2;
    /* Grr_shared_3 represents Grr[RC_A,RC_A], Grr[RC_B,RC_B], Grr[RC_C,RC_C]: Grc. */
    Grr_shared_3 = Grc;
    /* Grr_P_P represents Grr[P,P]: PP. */
    Grr_P_P = PP;
    /* Grr_shared_4 represents Grr[P,N], Grr[N,P]: PN. */
    Grr_shared_4 = PN;
    /* Grr_N_N represents Grr[N,N]: gNN. */
    Grr_N_N = gNN;
    /* Grk_shared_1 represents Grk[A_1,k1], Grk[B_1,k2], Grk[C_1,k3]: G12. */
    Grk_shared_1 = G12;
    /* Grk_shared_2 represents Grk[A_1,k3], Grk[B_1,k1], Grk[C_1,k2]: -G12. */
    Grk_shared_2 = -G12;
    /* Grk_shared_3 represents Grk[G,k1], Grk[G,k2], Grk[G,k3]: -G22 - w2. */
    Grk_shared_3 = -G22 - w2;
    /* Grk_shared_4 represents Grk[RC_A,k1], Grk[RC_B,k2], Grk[RC_C,k3]: -Grc. */
    Grk_shared_4 = -Grc;
    /* Grk_P_k1 represents Grk[P,k1]: AP. */
    Grk_P_k1 = AP;
    /* Grk_P_k2 represents Grk[P,k2]: BP. */
    Grk_P_k2 = BP;
    /* Grk_P_k3 represents Grk[P,k3]: CP. */
    Grk_P_k3 = CP;
    /* Grk_N_k1 represents Grk[N,k1]: AN. */
    Grk_N_k1 = AN;
    /* Grk_N_k2 represents Grk[N,k2]: BN. */
    Grk_N_k2 = BN;
    /* Grk_N_k3 represents Grk[N,k3]: CN. */
    Grk_N_k3 = CN;
    /* Gkr_shared_1 represents Gkr[k1,A_1], Gkr[k2,B_1], Gkr[k3,C_1]: G12. */
    Gkr_shared_1 = G12;
    /* Gkr_shared_2 represents Gkr[k1,B_1], Gkr[k2,C_1], Gkr[k3,A_1]: -G12. */
    Gkr_shared_2 = -G12;
    /* Gkr_shared_3 represents Gkr[k1,G], Gkr[k2,G], Gkr[k3,G]: -G22 - w2. */
    Gkr_shared_3 = -G22 - w2;
    /* Gkr_shared_4 represents Gkr[k1,RC_A], Gkr[k2,RC_B], Gkr[k3,RC_C]: -Grc. */
    Gkr_shared_4 = -Grc;
    /* Gkr_k1_P represents Gkr[k1,P]: AP. */
    Gkr_k1_P = AP;
    /* Gkr_k1_N represents Gkr[k1,N]: AN. */
    Gkr_k1_N = AN;
    /* Gkr_k2_P represents Gkr[k2,P]: BP. */
    Gkr_k2_P = BP;
    /* Gkr_k2_N represents Gkr[k2,N]: BN. */
    Gkr_k2_N = BN;
    /* Gkr_k3_P represents Gkr[k3,P]: CP. */
    Gkr_k3_P = CP;
    /* Gkr_k3_N represents Gkr[k3,N]: CN. */
    Gkr_k3_N = CN;
    /* Gkk_shared_1 represents Gkk[k1,k1], Gkk[k2,k2], Gkk[k3,k3]: Dabc + G22 + Grc + w2. */
    Gkk_shared_1 = Dabc + G22 + Grc + w2;
    /* W_shared_1 represents W[1,1], W[2,2], W[3,3]: 1.0/(Dabc + G22 + Grc + w2). */
    W_shared_1 = 1.0/(Dabc + G22 + Grc + w2);
    set_CODE(&Grr_code, 0, 0, Grr_shared_1);
    set_CODE(&Grr_code, 1, 1, Grr_shared_1);
    set_CODE(&Grr_code, 2, 2, Grr_shared_1);
    set_CODE(&Grr_code, 0, 1, Grr_shared_2);
    set_CODE(&Grr_code, 0, 2, Grr_shared_2);
    set_CODE(&Grr_code, 1, 0, Grr_shared_2);
    set_CODE(&Grr_code, 1, 2, Grr_shared_2);
    set_CODE(&Grr_code, 2, 0, Grr_shared_2);
    set_CODE(&Grr_code, 2, 1, Grr_shared_2);
    set_CODE(&Grr_code, 3, 3, Grr_G_G);
    set_CODE(&Grr_code, 4, 4, Grr_shared_3);
    set_CODE(&Grr_code, 5, 5, Grr_shared_3);
    set_CODE(&Grr_code, 6, 6, Grr_shared_3);
    set_CODE(&Grr_code, 7, 7, Grr_P_P);
    set_CODE(&Grr_code, 7, 8, Grr_shared_4);
    set_CODE(&Grr_code, 8, 7, Grr_shared_4);
    set_CODE(&Grr_code, 8, 8, Grr_N_N);
    set_CODE(&Grk_code, 0, 0, Grk_shared_1);
    set_CODE(&Grk_code, 1, 1, Grk_shared_1);
    set_CODE(&Grk_code, 2, 2, Grk_shared_1);
    set_CODE(&Grk_code, 0, 2, Grk_shared_2);
    set_CODE(&Grk_code, 1, 0, Grk_shared_2);
    set_CODE(&Grk_code, 2, 1, Grk_shared_2);
    set_CODE(&Grk_code, 3, 0, Grk_shared_3);
    set_CODE(&Grk_code, 3, 1, Grk_shared_3);
    set_CODE(&Grk_code, 3, 2, Grk_shared_3);
    set_CODE(&Grk_code, 4, 0, Grk_shared_4);
    set_CODE(&Grk_code, 5, 1, Grk_shared_4);
    set_CODE(&Grk_code, 6, 2, Grk_shared_4);
    set_CODE(&Grk_code, 7, 0, Grk_P_k1);
    set_CODE(&Grk_code, 7, 1, Grk_P_k2);
    set_CODE(&Grk_code, 7, 2, Grk_P_k3);
    set_CODE(&Grk_code, 8, 0, Grk_N_k1);
    set_CODE(&Grk_code, 8, 1, Grk_N_k2);
    set_CODE(&Grk_code, 8, 2, Grk_N_k3);
    set_CODE(&Gkr_code, 0, 0, Gkr_shared_1);
    set_CODE(&Gkr_code, 1, 1, Gkr_shared_1);
    set_CODE(&Gkr_code, 2, 2, Gkr_shared_1);
    set_CODE(&Gkr_code, 0, 1, Gkr_shared_2);
    set_CODE(&Gkr_code, 1, 2, Gkr_shared_2);
    set_CODE(&Gkr_code, 2, 0, Gkr_shared_2);
    set_CODE(&Gkr_code, 0, 3, Gkr_shared_3);
    set_CODE(&Gkr_code, 1, 3, Gkr_shared_3);
    set_CODE(&Gkr_code, 2, 3, Gkr_shared_3);
    set_CODE(&Gkr_code, 0, 4, Gkr_shared_4);
    set_CODE(&Gkr_code, 1, 5, Gkr_shared_4);
    set_CODE(&Gkr_code, 2, 6, Gkr_shared_4);
    set_CODE(&Gkr_code, 0, 7, Gkr_k1_P);
    set_CODE(&Gkr_code, 0, 8, Gkr_k1_N);
    set_CODE(&Gkr_code, 1, 7, Gkr_k2_P);
    set_CODE(&Gkr_code, 1, 8, Gkr_k2_N);
    set_CODE(&Gkr_code, 2, 7, Gkr_k3_P);
    set_CODE(&Gkr_code, 2, 8, Gkr_k3_N);
    set_CODE(&Gkk_code, 0, 0, Gkk_shared_1);
    set_CODE(&Gkk_code, 1, 1, Gkk_shared_1);
    set_CODE(&Gkk_code, 2, 2, Gkk_shared_1);

    /* ************************************************************************
     * CODE-SIDE IHIS VALUE SETUP
     * Update runtime Ihis/history-source values before per-step injection math.
     * Only non-direct Ihisred rows are computed through MATRIX_ CODE helpers.
     * ************************************************************************ */



    set_CODE(&Ihisr_code, 0, 0, Ihis_A - Ihis_C);
    set_CODE(&Ihisr_code, 1, 0, -Ihis_A + Ihis_B);
    set_CODE(&Ihisr_code, 2, 0, -Ihis_B + Ihis_C);
    set_CODE(&Ihisr_code, 3, 0, -Ihis_a - Ihis_b - Ihis_c);
    set_CODE(&Ihisr_code, 4, 0, -IAhis_rc);
    set_CODE(&Ihisr_code, 5, 0, -IBhis_rc);
    set_CODE(&Ihisr_code, 6, 0, -IChis_rc);
    set_CODE(&Ihisr_code, 7, 0, Ihis_exclude_c3);
    set_CODE(&Ihisr_code, 8, 0, Ihis_exclude_c4);
    set_CODE(&Ihisk_code, 0, 0, IAhis_rc + Ihis_a + Ihis_exclude_c0);
    set_CODE(&Ihisk_code, 1, 0, IBhis_rc + Ihis_b + Ihis_exclude_c1);
    set_CODE(&Ihisk_code, 2, 0, IChis_rc + Ihis_c + Ihis_exclude_c2);

    /* Sliced Schur sparse updates for dynamic Gred entries.
       Each assignment uses Gred[i,j] = Grr[i,j] - Grk[i,k] * W * Gkr[k,j]. */
    /* Stamp dynamic Gred entries directly from the sliced dynamic block. */
    /* varG_A_1_A_1 represents Gred[A_1,A_1]: Grr_shared_1 - Grk_shared_1*W_shared_1*Gkr_shared_1 - Grk_shared_2*W_shared_1*Gkr_shared_2. */
    /* Gred[A_1,A_1] = Grr[A_1,A_1] - Grk[A_1,k] * W * Gkr[k,A_1]. */
    varG_A_1_A_1 = Grr_shared_1 - Grk_shared_1*W_shared_1*Gkr_shared_1 - Grk_shared_2*W_shared_1*Gkr_shared_2;
    /* varG_A_1_B_1 represents Gred[A_1,B_1]: Grr_shared_2 - Grk_shared_1*W_shared_1*Gkr_shared_2. */
    /* Gred[A_1,B_1] = Grr[A_1,B_1] - Grk[A_1,k] * W * Gkr[k,B_1]. */
    varG_A_1_B_1 = Grr_shared_2 - Grk_shared_1*W_shared_1*Gkr_shared_2;
    /* varG_A_1_C_1 represents Gred[A_1,C_1]: Grr_shared_2 - Grk_shared_2*W_shared_1*Gkr_shared_1. */
    /* Gred[A_1,C_1] = Grr[A_1,C_1] - Grk[A_1,k] * W * Gkr[k,C_1]. */
