RAM_PASS1:
    /* Decode the optional global case selector into per-element local cases. */
    switch (case_id) {
    case 0: /* case 0: Trf_D/Y = Y/D; YBox3 = Y; C1=case0, C3=case0 */
        C1_case_id = 0;
        C3_case_id = 0;
        break;
    case 1: /* case 1: Trf_D/Y = Y/D; YBox3 = D; C1=case0, C3=case1 */
        C1_case_id = 0;
        C3_case_id = 1;
        break;
    case 2: /* case 2: Trf_D/Y = D/Y; YBox3 = Y; C1=case1, C3=case0 */
        C1_case_id = 1;
        C3_case_id = 0;
        break;
    case 3: /* case 3: Trf_D/Y = D/Y; YBox3 = D; C1=case1, C3=case1 */
        C1_case_id = 1;
        C3_case_id = 1;
        break;
    default:
        C1_case_id = 0;
        C3_case_id = 0;
        break;
    }
    /* Resolve RAM multi-case effective aliases as full values, never deltas. */
    switch (C3_case_id) {
    case 0:
        multcase_G_C3_N10_N10 = Grc;
        multcase_G_C3_N10_N5 = Grc;
        break;
    case 1:
        multcase_G_C3_N10_N10 = 1.0;
        multcase_G_C3_N10_N5 = 0.0;
        break;
    default:
        multcase_G_C3_N10_N10 = Grc;
        multcase_G_C3_N10_N5 = Grc;
        break;
    }
    /* Retained layout is selected during initialization. Runtime profile switching is not supported. */
    if (case_id == 0 || case_id == 2) {
        retained_profile = PACK_CASE_0;
        node_active = RETAINED_NODES_CASE_0;
    }
    else if (case_id == 1 || case_id == 3) {
        retained_profile = PACK_CASE_1;
        node_active = RETAINED_NODES_CASE_1;
    }
    int err = 0;
    /* ************************************************************************
     * RAM-SIDE G MATRIX VALUE SETUP
     * Assign or compute every G-related value before any RAM-side use.
     * This section stamps only fixed g_mat_over entries; CODE-owned matrices are refreshed in CODE.
