    double varG_P_RC_C = createGValue("varG_P_RC_C", "P", "RC_C", 0, "case_id == 0 || case_id == 2");
    double varG_N_N = createGValue("varG_N_N", "N", "N", 0, "TRUE");
    double varG_N_RC_A = createGValue("varG_N_RC_A", "N", "RC_A", 0, "case_id == 0 || case_id == 2");
    double varG_N_RC_B = createGValue("varG_N_RC_B", "N", "RC_B", 0, "case_id == 0 || case_id == 2");
    double varG_N_RC_C = createGValue("varG_N_RC_C", "N", "RC_C", 0, "case_id == 0 || case_id == 2");
    double varG_RC_A_RC_A = createGValue("varG_RC_A_RC_A", "RC_A", "RC_A", 0, "case_id == 0 || case_id == 2");
    double varG_RC_A_RC_B = createGValue("varG_RC_A_RC_B", "RC_A", "RC_B", 0, "case_id == 0 || case_id == 2");
    double varG_RC_A_RC_C = createGValue("varG_RC_A_RC_C", "RC_A", "RC_C", 0, "case_id == 0 || case_id == 2");
    double varG_RC_B_RC_B = createGValue("varG_RC_B_RC_B", "RC_B", "RC_B", 0, "case_id == 0 || case_id == 2");
