    double varG_RC_C_RC_C = createGValue("varG_RC_C_RC_C", "RC_C", "RC_C", 0, "case_id == 0 || case_id == 2");

CODE:
BEGIN_T0:
    if (!rtds_matrix_code_ready) {
        initializeMatricesForCode();
        conditionMatrixForCODE(&Grr_code);
        conditionMatrixForCODE(&Grk_code);
        conditionMatrixForCODE(&Gkr_code);
        conditionMatrixForCODE(&Gkk_code);
        conditionMatrixForCODE(&Gred_code);
        conditionMatrixForCODE(&W_code);
        conditionMatrixForCODE(&Ihisr_code);
        conditionMatrixForCODE(&Ihisred_code);
        conditionMatrixForCODE(&Ihisk_code);
        conditionMatrixForCODE(&Vr_code);
        conditionMatrixForCODE(&tmp_Grk_W_code);
        conditionMatrixForCODE(&tmp_Grk_W_Gkr_code);
        conditionMatrixForCODE(&tmp_Grk_W_Ihisk_code);
        conditionMatrixForCODE(&Vk_code);
        conditionMatrixForCODE(&tmp_W_Gkr_code);
        conditionMatrixForCODE(&tmp_W_Gkr_Vr_code);
        conditionMatrixForCODE(&tmp_W_Ihisk_code);
        conditionMatrixForCODE(&tmp_Vk_sum_code);
        rtds_matrix_code_ready = 1;
    }


    /* ************************************************************************
     * CODE-SIDE G MATRIX VALUE SETUP
     * Update runtime G-related symbols and matrices before the reduction math below.
     * Only matrices required by dynamic G, Ihis reduction, or Vk recovery are refreshed.
     * ************************************************************************ */


    /* Resolve CODE multi-case effective aliases as full values, never deltas. */
    switch (C1_case_id) {
    case 0:
        multcase_G_C1_N1_N1 = G11 + w1;
        multcase_G_C1_N1_N6 = G12;
        multcase_G_C1_N4_N4 = 3.0*G11 + 3.0*w1;
        multcase_G_C1_N4_N5 = 0.0;
        break;
    case 1:
        multcase_G_C1_N1_N1 = 2.0*G11 + 2.0*w1;
        multcase_G_C1_N1_N6 = 0.0;
        multcase_G_C1_N4_N4 = 3.0*G22 + 3.0*w2;
        multcase_G_C1_N4_N5 = G22 + w2;
        break;
    default:
        multcase_G_C1_N1_N1 = G11 + w1;
        multcase_G_C1_N1_N6 = G12;
        multcase_G_C1_N4_N4 = 3.0*G11 + 3.0*w1;
        multcase_G_C1_N4_N5 = 0.0;
        break;
    }
    switch (runtime_UCM_block_case_id) {
    case 0:
        multcase_G_C2_N5_N5 = AA;
        multcase_G_C2_N6_N6 = BB;
        multcase_G_C2_N7_N7 = CC;
        break;
    case 1:
        multcase_G_C2_N5_N5 = Dabc;
        multcase_G_C2_N6_N6 = Dabc;
        multcase_G_C2_N7_N7 = Dabc;
        break;
    default:
        multcase_G_C2_N5_N5 = AA;
        multcase_G_C2_N6_N6 = BB;
        multcase_G_C2_N7_N7 = CC;
        break;
    }
    switch (case_id) {
    case 0:
        multcase_G_combined_N5_N5 = 2.0*G22 + Grc + 2.0*w2;
        break;
    case 1:
        multcase_G_combined_N5_N5 = 2.0*G22 + 2.0*Grc + 2.0*w2;
        break;
    case 2:
        multcase_G_combined_N5_N5 = G22 + Grc + w2;
        break;
    case 3:
        multcase_G_combined_N5_N5 = G22 + 2.0*Grc + w2;
        break;
    default:
        multcase_G_combined_N5_N5 = 2.0*G22 + Grc + 2.0*w2;
        break;
    }
    /* Resolve CODE_PER_STEP multi-case effective aliases as full values, never deltas. */
    switch (C1_case_id) {
    case 0:
        multcase_Ihis_C1_N1 = Ihis_A;
        multcase_Ihis_C1_N2 = Ihis_B;
        multcase_Ihis_C1_N3 = Ihis_C;
        multcase_Ihis_C1_N4 = Ihis_A + Ihis_B + Ihis_C;
        break;
    case 1:
        multcase_Ihis_C1_N1 = Ihis_A - Ihis_C;
        multcase_Ihis_C1_N2 = -Ihis_A + Ihis_B;
        multcase_Ihis_C1_N3 = -Ihis_B + Ihis_C;
        multcase_Ihis_C1_N4 = Ihis_a + Ihis_b + Ihis_c;
        break;
    default:
        multcase_Ihis_C1_N1 = Ihis_A;
        multcase_Ihis_C1_N2 = Ihis_B;
        multcase_Ihis_C1_N3 = Ihis_C;
        multcase_Ihis_C1_N4 = Ihis_A + Ihis_B + Ihis_C;
        break;
    }
    switch (C3_case_id) {
    case 0:
        multcase_Ihis_C3_N10 = IAhis_rc;
        multcase_Ihis_C3_N11 = IBhis_rc;
        multcase_Ihis_C3_N12 = IChis_rc;
        break;
    case 1:
        multcase_Ihis_C3_N10 = 0.0;
        multcase_Ihis_C3_N11 = 0.0;
        multcase_Ihis_C3_N12 = 0.0;
        break;
    default:
        multcase_Ihis_C3_N10 = IAhis_rc;
        multcase_Ihis_C3_N11 = IBhis_rc;
        multcase_Ihis_C3_N12 = IChis_rc;
        break;
    }
    switch (case_id) {
    case 0:
        multcase_Ihis_combined_N5 = IAhis_rc + Ihis_a - Ihis_c + Ihis_exclude_c0;
        multcase_Ihis_combined_N6 = IBhis_rc - Ihis_a + Ihis_b + Ihis_exclude_c1;
        multcase_Ihis_combined_N7 = IChis_rc - Ihis_b + Ihis_c + Ihis_exclude_c2;
        break;
    case 1:
        multcase_Ihis_combined_N5 = IAhis_rc - IChis_rc + Ihis_a - Ihis_c + Ihis_exclude_c0;
        multcase_Ihis_combined_N6 = -IAhis_rc + IBhis_rc - Ihis_a + Ihis_b + Ihis_exclude_c1;
        multcase_Ihis_combined_N7 = -IBhis_rc + IChis_rc - Ihis_b + Ihis_c + Ihis_exclude_c2;
        break;
    case 2:
        multcase_Ihis_combined_N5 = IAhis_rc + Ihis_a + Ihis_exclude_c0;
        multcase_Ihis_combined_N6 = IBhis_rc + Ihis_b + Ihis_exclude_c1;
        multcase_Ihis_combined_N7 = IChis_rc + Ihis_c + Ihis_exclude_c2;
        break;
    case 3:
        multcase_Ihis_combined_N5 = IAhis_rc - IChis_rc + Ihis_a + Ihis_exclude_c0;
        multcase_Ihis_combined_N6 = -IAhis_rc + IBhis_rc + Ihis_b + Ihis_exclude_c1;
        multcase_Ihis_combined_N7 = -IBhis_rc + IChis_rc + Ihis_c + Ihis_exclude_c2;
        break;
    default:
        multcase_Ihis_combined_N5 = IAhis_rc + Ihis_a - Ihis_c + Ihis_exclude_c0;
        multcase_Ihis_combined_N6 = IBhis_rc - Ihis_a + Ihis_b + Ihis_exclude_c1;
        multcase_Ihis_combined_N7 = IChis_rc - Ihis_b + Ihis_c + Ihis_exclude_c2;
        break;
    }
    /* Runtime refresh. Use set_CODE for matrices touched in CODE; do not write MATRIX_.p directly. */
